"season": null,
"home": false,
"care": null,
"persona": "我要到七十五岁往后才开始长手臂，活到两百岁也不稀奇。在亚利桑那，砍我是犯法的。",
"facts": [
"通常能活 150 到 200 年，一般要到 75 到 100 岁才长出第一根侧枝，有的一辈子都不长。",
"下过雨后它会把水吸进身体、明显膨胀，吸饱水的成年巨人柱能重 1.5 到 2.2 吨。",
"在亚利桑那州，砍倒一株巨人柱属于四级重罪。它的花是该州州花，夜里开放，主要的夜间传粉者是小长鼻蝠。"
],
