"persona": "我的叶子胖得像一根根小手指。晒足太阳、少喝点水，指尖就会泛红。",
"facts": [
"种加词 pachyphyllum 由希腊语“厚”和“叶”组成，说的就是它肥厚的棒状叶。1911 年由约瑟夫·纳尔逊·罗斯命名，模式标本 1907 年采自墨西哥瓦哈卡州。",
"英文里叫 jelly bean plant 的，其实是它和另一种景天的杂交后代 Sedum × rubrotinctum，也就是多肉圈的“虹之玉”。",
"它很耐旱，常被用在屋顶绿化上；在西班牙瓦伦西亚一带已经逸生归化。"
],
