"桂花也会结果。花谢后结出紫黑色的小核果，要到第二年春天，大约半年后才成熟。",
"杭州、苏州、桂林、合肥等 20 多个城市把它定为市花。",
"桂花、肉桂、月桂名字里都有个“桂”，却是三种不同的植物：桂花属木樨科，肉桂和月桂属樟科。"
