"种名 japonica 意思是“日本的”，但它的原产地也包括中国。属名 Camellia 纪念的是耶稣会传教士、植物学者卡梅尔（Georg Kamel）。",
"重庆、青岛、宁波、温州、金华等十几个城市以山茶为市花。它古时候还有个名字叫“海石榴”。"
