"persona": "我名字里有个“梅”，但我和梅花没有亲戚关系。",
"facts": [
"李时珍在《本草纲目》里就说它“非梅类”，只是和梅同时开、香气相近、颜色像蜜蜡，才叫蜡梅。按现在的分类，它属蜡梅科，梅属蔷薇科。",
"据明代王世懋考证，北宋元祐年间，苏轼和黄庭坚见这种黄花像蜜蜡，给它定名“蜡梅”，从此名气大起来。也常写作“腊梅”，因为它在腊月开。",
"它也被引种到伊朗，波斯语叫它“冰之花”（gol-e yakh），在波斯诗歌和音乐里常常出现。"
],
