"persona": "江南的“梅雨”，就是照着我的果子成熟的时节起的名。",
"facts": [
"英文常把它叫作 plum（李），但它在李属里被归入杏组，和杏更近。",
"人们吃梅子的历史很长：江苏吴江的遗址里出土过约 5000 年前的梅核。《尚书》里“若作和羹，尔惟盐梅”，说的是做羹汤要靠盐和梅子调味。",
"画里的梅常在雪中开，可大多数梅花品种并不太耐寒，在长江以北没法露地过冬。20 世纪中期以后，陈俊愉等人才育出能在北方越冬的品种。"
],
"kin": {
"text": "蔷薇科李属，和杏最近，樱花、月季也在这个科",
"ids": [
"sakura",
"chinarose"
]
},
"poem": {
"line": "疏影横斜水清浅，暗香浮动月黄昏。",
"src": "林逋《山园小梅》"
},
