"home": true,
"care": {
"light": 3,
"water": 2,
"diff": 1,
"every": 3,
"tip": "喜光，盆土表面干了再浇透。想让它按时开花，入秋后晚上别放在一直亮灯的地方。"
},
"persona": "我看白天的长短来决定什么时候开花。秋天夜一长，我就知道该开了。",
"facts": [
"它是短日照植物，白天变短才开始分化花芽。花农秋天在夜里补光推迟花期，夏天用黑幕遮光提前花期，所以一年四季都能买到菊花。",
"日本皇室的家纹是菊花，据记载从后鸟羽上皇时开始使用，日本皇位也因此被称作“菊花王朝”。",
"据 2014 年的估计，全世界的菊花品种超过两万个，其中中国约有七千个。"
],
"kin": {
"text": "菊科，和向日葵、蒲公英是一家",
"ids": [
"sunflower",
"dandelion"
]
},
"poem": {
"line": "采菊东篱下，悠然见南山。",
"src": "陶渊明《饮酒·其五》"
},
