"home": false,
"care": null,
"persona": "17 世纪的荷兰，我的一个球根能卖到工匠十年的收入。",
"facts": [
"1637 年 2 月，荷兰的“郁金香狂热”到达顶点，个别球根卖到熟练工匠年收入的 10 倍以上，随后迅速崩盘。它常被看作有记录的第一次投机泡沫。",
"当年最受追捧的条纹郁金香，花纹是病毒造成的：病毒抑制了花青素，花瓣的白色或黄色底色露出来，形成条纹。",
"tulip 这个词一般认为来自土耳其语 tülbend（细纱布），可能源于波斯语的“头巾”。一种说法是早年翻译出了错：奥斯曼人有在头巾上插郁金香的风气。"
],
"kin": {
"text": "百合科，和百合是一家",
"ids": []
},
"poem": null,
"sources": [
"https://en.wikipedia.org/wiki/Tulipa_gesneriana",
"https://en.wikipedia.org/wiki/Tulip",
"https://en.wikipedia.org/wiki/Tulip_mania",
"https://zh.wikipedia.org/wiki/%E9%83%81%E9%87%91%E9%A6%99"
],
