"persona": "你夸我颜色好看，夸的是我的苞片。我真正的花，是中间那几朵白色小管子。",
"facts": [
"鲜艳的“花瓣”是苞片，每三片苞片围着三朵白色的小花。苞片薄得像纸，所以英文又叫它 paper flower。",
"属名纪念法国航海家布干维尔。随他环球航行的植物学家科默森最早描述了这类植物，1789 年才正式发表。",
"它是深圳、厦门、珠海的市花，也是海南的省花。"
],
