"persona": "我爬架子是逆时针往上绕的，日本紫藤正好反过来。分不清我们俩，就看藤。",
"facts": [
"从上往下看，紫藤的茎按逆时针缠绕，日本紫藤按顺时针，这是区分两者的一个简便办法。",
"美国加州马德雷山有一株 19 世纪 90 年代种下的紫藤，覆盖面积约一英亩（约 4000 平方米），被吉尼斯世界纪录认定为世界上最大的开花植物。",
"全株含紫藤苷，种子毒性最强。豆荚好看，别让小孩拿来玩或吃。"
],
