"persona": "我一年四季都是绿的，可每年春天都要换一次叶子。地上落满红叶的时候，别以为我病了。",
"facts": [
"香樟的叶子大约能活两年。每年三到五月新叶长出来，老叶就集中变红脱落，所以这种常绿树会在春天落叶。",
"樟脑曾是赛璐珞和无烟火药的重要原料。日本殖民统治台湾之前和期间，樟脑一直是台湾的大宗产业。",
"它以前的学名是 Cinnamomum camphora，和肉桂同属。2022 年的分子研究把它分到了单独的樟属 Camphora，研究认为这一支和檫木属更近。"
],
"kin": {
"text": "樟科，和牛油果、肉桂同科",
"ids": [
"avocado"
]
},
"poem": null,
