"facts": [
"大家都觉得它的叶子像手：中文说像鸡爪，种名 palmatum 意思是“手掌状”，日文名 kaede 和 momiji 分别联想到青蛙的手和婴儿的手。",
"“槭”和“枫香”是两类树：槭树叶子对生，果实是一对带翅的翅果；枫香叶子互生，多为三裂，果实是带刺的小球。",
"它的园艺品种超过一千个，大多靠嫁接繁殖，叶形和叶色差别很大。"
],
