"facts": [
"花的直径可达 30 厘米，带柠檬似的香气。种名 grandiflora 就是“大花的”。",
"木兰类植物出现得比蜜蜂早，一般认为它们的花是适应甲虫传粉演化出来的，心皮常被来访的甲虫啃坏。",
"美国白宫南门廊旁曾有一棵杰克逊总统近 200 年前种下的广玉兰，是白宫院内最老的树，2018 年初被移除。"
],
