"facts": [
"它的果序是带刺的小圆球。蒴果裂开后，种子从许多小孔里掉出来，像四通八达的孔道，所以中药里叫它“路路通”。",
"种名 formosana 意思是“台湾的”，模式标本是 1864 年在台湾淡水采到的。",
"在原产地，人们用它的木材做茶叶箱，叶子还能拿来喂蚕。"
],
