"persona": "夏天我落一地黄花，秋天挂满一树小灯笼。",
"facts": [
"古书记载周代按身份在墓旁种树：天子种松，诸侯种柏，大夫种栾，士种杨。所以栾树也被叫作“大夫树”。",
"黄花凋落时纷纷如雨，英文叫它 goldenrain tree。果实是中空的膜质蒴果，像一个个小灯笼。",
"据记载，它的花可以做黄色染料；叶子虽是绿的，和白布一起煮却能把布染黑，所以民间也叫它“乌叶子树”。"
],
