"persona": "秋天我的叶子会变红变紫。叶子落光后，枝头还挂着一粒粒白色的种子。",
"facts": [
"种子外面裹着一层白色蜡质，可以做蜡烛和肥皂，种名 sebifera 的意思就是“带油脂的”。在中国，它作为经济作物栽种已有上千年。",
"据说是本杰明·富兰克林把它引进美国的，他在 1772 年的信里提到得到了它的种子，也有人认为引种者另有其人。如今它在美国南部是入侵物种。",
"它的汁液和叶子被认为有毒，花蜜却无毒，是养蜂人看重的蜜源植物。"
],
