"荚果年轻时是绿色、软的，成熟后变成深褐色的木质长荚，最长可达 60 厘米。",
"它是厦门、汕头和台南的市树。台湾 1897 年引入后，因为六月盛开，常和蝉鸣一起被当作毕业季的象征。"
