"persona": "我年轻时树干上长满圆锥形的刺。开花的时候，我一片叶子都不留。",
"facts": [
"它是广州的市花。花季常有老人在树下捡落花，晒干后煲汤或泡茶，木棉花也是广东凉茶“五花茶”的材料之一。",
"在森林里，它的树冠常常高出周围的树，所以被叫作“英雄树”。",
"果实成熟裂开后，里面是像棉絮的白色纤维，可以填枕头。英文 kapok 有时也指美洲的吉贝（Ceiba pentandra），那是另一种树。"
],
