"facts": [
"它的小叶到了夜里或下雨时会慢慢合拢。现代波斯语里它的名字意思是“夜里睡觉的”，中文名“合欢”也和这个习性有关。",
"那一团粉红色的“丝”主要是雄蕊，每根长 2 到 3 厘米，真正的花萼和花冠很小。",
"18 世纪中叶，意大利贵族阿尔比齐把它带到欧洲，合欢属就以他命名。种名 julibrissin 由波斯语“丝绸之花”讹变而来。"
],
