"facts": [
"果皮含皂素，加水揉搓就会起泡，在亚洲一直被当作清洁剂用到 20 世纪初。属名 Sapindus 的意思是“印度的肥皂”。",
"“无患”这个名字来自一个传说：用它的木头做的棒子能驱鬼，所以它又叫“鬼见愁”。",
"黑色的种子坚硬圆滑，佛经《佛说木槵子经》里讲到用一百零八颗木槵子串成念珠。"
],
