"persona": "森林着过火以后，常常是我最先长回来。",
"facts": [
"桦树是典型的先锋树种，森林被火烧或采伐后，往往最先长出成片的桦树林。",
"白色的树皮会一层层像纸一样剥落。桦树皮含油脂，即使湿了也很好烧，是野外引火的好材料。",
"鄂伦春、鄂温克、达斡尔等民族用桦树皮做船、篓、箱、盒、碗，在生活中代替了陶器和瓷器。桦树皮制作技艺 2006 年列入第一批国家级非物质文化遗产。"
],
