"facts": [
"deodar 来自梵语 devadāru，意思是“众神之木”，在印度教里它被当作神树。",
"它是巴基斯坦的国树，也是印度喜马偕尔邦的邦树。",
"木材耐腐、防虫。克什米尔斯利那加有名的船屋就用它建造，喜马偕尔邦一些地方用它的木头盖储粮的屋子。"
],
