"facts": [
"果实成熟前会裂成几片小船似的果瓣，种子就长在果瓣边缘。据说种子炒熟后可以泡茶。",
"幼树的树皮是绿色、光滑的，所以又叫青桐。它和同样带“桐”字的油桐、泡桐、“法国梧桐”都没有亲缘关系。",
"它的木材声学特性和泡桐相近，古时两者常被混称为“桐”，可以用来做古琴、古筝的面板。"
],
