"persona": "你挠挠我的树干，我的枝叶就跟着抖。别误会，我并不怕痒。",
"facts": [
"它的老树皮每年脱落，树干很光滑。轻挠树干，树梢的枝叶会跟着晃，所以叫“痒痒树”。原因说法不一，常见的解释是振动顺着坚硬的枝干传到繁茂的树冠上被放大了。",
"唐开元元年（713 年），中书省一度改名紫微省，中书舍人也被称作“紫微郎”。白居易任中书舍人时写下了“紫薇花对紫微郎”。",
"花瓣皱得像绉纱，英文叫 crape myrtle。属名纪念瑞典人拉格斯特伦，是他把标本提供给了林奈。"
],
