"persona": "我的叶子是一对一对长的。每次你掐掉我的尖儿，叶腋里就会冒出两根新枝。",
"facts": [
"台湾三杯鸡里的\"九层塔\"就是罗勒在台湾的叫法，香港和潮汕一带还叫它\"鱼生菜\"。",
"北魏的《齐民要术》记载，北方人把罗勒叫作\"兰香\"，是为了避后赵皇帝石勒的名讳。",
"一根枝条开花以后，就不再长新叶，茎会变得木质化，叶子里的精油也会减少，所以种罗勒的人会早早把花穗掐掉。"
],
