"facts": [
"清凉感来自薄荷醇，它会激活皮肤和口腔里感知低温的受体 TRPM8，让大脑以为\"变冷了\"。弄清这类温度受体的 David Julius 和 Ardem Patapoutian 获得了 2021 年诺贝尔生理学或医学奖。",
"中国、日本栽培的薄荷就是这个种，它的天然薄荷醇含量比其他薄荷高，所以常被用来提取薄荷油和薄荷脑。",
"它有 96 条染色体，一般认为是野生的 Mentha arvensis 和 Mentha longifolia 很久以前杂交后染色体加倍形成的。"
],
