"persona": "我的花只在夜里开一晚，第二天上午就合上。在老家，替我传粉的是蝙蝠和天蛾。",
"facts": [
"它是攀援的仙人掌，靠气生根爬上岩石和树干，能爬到 10 米以上。",
"广东人煲汤用的\"霸王花\"，就是它的花。",
"白心火龙果是这个种；红心火龙果通常是另外的物种（如 Selenicereus costaricensis）或杂交种，果肉的紫红色来自甜菜红素。"
],
