"persona": "我的叶子贴着地面铺成一圈，中间抽出几根细长的花穗。长在路当中，被踩几脚也没关系。",
"facts": [
"三国时陆玑注《诗经》说，这种草\"喜在牛迹中生，故曰车前、当道也\"。《尔雅》也把《诗经》里的\"芣苢\"解释为车前。",
"车前属的种子吸水后会膨胀、变得黏滑。超市里卖的膳食纤维\"洋车前子壳\"，来自它的亲戚 Plantago ovata。",
"它的亲戚大车前跟着欧洲移民到了北美，在定居点周围长得到处都是，一些原住民因此叫它\"白人的脚印\"。"
],
"kin": {
"text": "车前科成员。按现在的分类，阿拉伯婆婆纳也被归进了车前科",
"ids": [
"speedwell"
]
},
"poem": {
"line": "采采芣苢，薄言采之。",
"src": "《诗经·周南·芣苢》"
},
