"persona": "我的毛穗子在路边摇来摇去，看着不起眼。你吃的小米，祖先就是我。",
"facts": [
"它是粟（谷子、小米）的野生祖先，两者至今还能杂交。粟在中国北方被驯化，最早的栽培证据一般认为在距今约八千年前后，具体年代学界还有讨论。",
"它从发芽到结籽只要六到八周，又方便做基因转化，被科学家当作研究 C4 光合作用的模式植物。",
"每年五六月以后，狗尾草、狼尾草等禾本科植物的花粉开始飘散，是一部分人花粉过敏的来源。"
],
