"persona": "我有三片心形的小叶和五瓣小黄花。太阳一躲起来，我的花就合上睡觉。",
"facts": [
"它的蒴果成熟后会突然裂开，把约 1 毫米长的种子弹射出去，这是它在花盆和草坪里到处冒出来的原因之一。",
"小叶尝起来有柠檬一样的酸味，可以泡水喝。不过酢浆草属植物含草酸，长期大量吃会影响钙的吸收。",
"它是酢浆灰蝶幼虫的食物。日本福岛核事故后，研究者在这种小蝴蝶身上观察到异常个体增多，用它来评估辐射对生物的影响。"
],
