"home": false,
"care": null,
"persona": "我名字里有\"阿拉伯\"，学名里写着\"波斯\"，老家其实在高加索和伊朗北部。",
"facts": [
"种名 persica 的意思是\"波斯的\"，所以它也叫波斯婆婆纳。如今它几乎遍布全球，是婆婆纳属里分布最广的一种。",
"它在中国是外来植物，上海植物志标注为\"外来种、极常见\"。2014 年一项全国入侵植物分级研究把它列为 3 级，危害比一年蓬、加拿大一枝黄花（1 级）轻。",
"早春草坪和田边那片天蓝色小花常常就是它。花冠约 1 厘米宽，有深色条纹和白色花心，单朵长在细长的花梗上，花梗比旁边的苞片长出不少。"
],
"kin": {
"text": "按现在的分类属车前科，和车前是一家",
"ids": [
"plantain"
]
},
"poem": null,
