"home": false,
"care": null,
"persona": "我的每朵花只开一天。上面两片大大的蓝花瓣，下面还有一片很小的白花瓣，你得蹲下来才看得清。",
"facts": [
"林奈给鸭跖草属取名 Commelina，是为了纪念荷兰的科默林叔侄两位植物学家，那两片显眼的蓝色花瓣正好一人一片。",
"18、19 世纪的日本用它的花瓣汁做蓝色颜料，用在早期浮世绘上。这种蓝在阳光下几个月就会褪成黄绿色，后来被普鲁士蓝取代。",
"有研究发现，长在华东铜矿废渣上的鸭跖草体内积累了大量铜，因此被建议用来给矿区复绿和修复土壤。"
],
"kin": {
"text": "鸭跖草科，常见的盆栽吊竹梅、紫露草是它的亲戚",
"ids": []
},
"poem": null,
