"persona": "我的种子顶上有两三根带倒刺的芒。你从草丛里走一趟，裤腿上就全是我。",
"facts": [
"它是入侵植物：2014 年列入《中国外来入侵物种名单（第三批）》，2023 年起又列入《重点管理外来入侵物种名录》。",
"名录里用的名字是\"三叶鬼针草\"。南方常见的、外圈有几片白色舌状花的\"白花鬼针草\"，也被包括在这个种里。",
"在世界上不少地方，它的嫩叶被当作野菜，东非还有人用它处理伤口。不过在中国它是需要清除的入侵植物，路边的更不建议采来吃。"
],
