"facts": [
"它原产北美，19 世纪传入中国，2014 年被列入《中国外来入侵物种名单（第三批）》。",
"一株一年蓬一年能结 4 万多粒种子，不过发芽率只有约 5%。",
"它的头状花序只有 1～1.5 厘米宽，外围是两层细线形的舌状花，白色或带一点淡蓝，中间是黄色的管状花，常被误认作小雏菊。开花时，基部的莲座叶通常已经枯掉了。"
],
