"persona": "我在水边能长到三四米高，横着跑的茎一年能伸出 5 米多，走到哪儿就在哪儿扎根。",
"facts": [
"它的茎通常高 1.5～4 米，横走的茎一年能延伸 5 米以上，每隔一段就生根，所以一长就是一大片。",
"它的根系能过滤水里的杂质，人们用芦苇湿地来净化污水。欧洲传统的茅草屋顶，主要材料也是芦苇。",
"在北美，本地的芦苇亚种长势较弱；从欧洲带过去的亚种却四处扩张，挤占本地植物，成了入侵植物。"
],
