"它靠种子、匍匐茎和地下根状茎三条路扩张，茎节一碰到地面就生根，很快织成密实的草皮。",
"冬天或旱季它会休眠，叶子变成浅褐色，这是不少草坪冬天发黄的原因之一。在印度教里，它是供奉象头神的圣草。"
