"persona": "1935 年我被当作观赏花卉种进了上海、南京的花园，后来自己跑到了野外。",
"facts": [
"它是入侵植物：2010 年列入《中国外来入侵物种名单（第二批）》，2023 年起又列入《重点管理外来入侵物种名录》，浙江、上海、江苏一带危害最受关注。",
"一株大约能结 2 万粒带冠毛的小种子，随风飘得很远；地下还有横着长的根状茎，所以成片以后很难除尽。",
"秋天一片金黄时，它常被怪罪引起花粉过敏，真正的元凶通常是同时开花的豚草。"
],
