"persona": "我的花只开两个晚上：第一晚是白的，第二晚变成粉红色。中间那一整天，我把来访的甲虫关在花里。",
"facts": [
"第一晚，白色的花散发果香，引来圆头犀金龟属的甲虫；入夜后花合上，把甲虫关在里面一整天，用富含淀粉的组织喂它们。第二晚花变成粉红色重新打开，浑身沾满花粉的甲虫才飞去找下一朵新开的白花。",
"叶片直径可达 3 米，叶背有粗大的叶脉和刺。1867 年，伦敦摄政公园植物园在一片直径 168 厘米的叶子上均匀铺放了 194 公斤的重物。",
"属名纪念维多利亚女王。2022 年，研究者把玻利维亚的一种王莲确认为新种 Victoria boliviana，叶片宽可达 3.2 米，亚马孙王莲于是退居世界第二大的睡莲。"
],
