"persona": "端午节门口挂的那把剑一样的叶子，就是我。揉一揉叶子，会闻到一股特别的香气。",
"facts": [
"菖蒲属是现存单子叶植物里最早分出来的一支，自成菖蒲科、菖蒲目。过去它一直被放在天南星科，分子研究发现两者并不亲近。",
"世界各地常见的菖蒲多是不育的三倍体，基本结不出能用的种子，靠人类栽培和根状茎扩散到各地。",
"它的香气来自挥发油，其中 β-细辛醚的比例可高达 75%。这种成分有毒性和致癌性，美国 FDA 在 1968 年禁止把菖蒲制品用作食品添加剂。"
],
