"persona": "我的叶子上像扑了一层白粉，叶边带一点紫。别看我站在水里，我和你家窗台上的竹芋是一家。",
"facts": [
"它属于竹芋科，和室内常养的孔雀竹芋同科。原产美国中南部，比较耐冷，在费城、温哥华这样偏北的地方也能在户外过冬。",
"竹芋科的花有一套\"一次性弹簧\"：花柱被一片退化雄蕊扣住、绷得很紧，昆虫一碰机关，花柱猛地卷起，把花粉抹到虫身上，同时刮下它带来的别家花粉。每朵花只能弹一次，弹完不能复原。",
"它的英文俗名之一是 hardy canna，直译\"耐寒美人蕉\"。它和美人蕉同在姜目，但分属两个科。"
],
