"home": false,
"care": null,
"persona": "我是一种蕨，漂在水上过日子，一辈子不开花。水下那一缕缕像根的东西，是我的第三片叶子。",
"facts": [
"它的叶子三片一轮：两片平铺在水面，第三片沉在水下，细裂成须状，代替根的功能。它本身没有真正的根。",
"叶面密布细小的乳突和毛，能把水挡在外面，让叶子保持干爽、不易腐烂；叶子里还有气腔帮助漂浮。它不开花，靠长在植株基部的孢子果繁殖。",
"同属的 Salvinia molesta 叶面长着打蛋器形的毛，能在水下锁住一层空气。科学家把这种现象叫\"槐叶蘋效应\"，正在借鉴它研发能减少船体阻力的涂层。"
],
"kin": {
"text": "和满江红同属槐叶蘋目，按现行蕨类分类系统两者同科",
"ids": [
"azolla"
]
},
"poem": null,
"sources": [
"https://en.wikipedia.org/wiki/Salvinia_natans",
"https://en.wikipedia.org/wiki/Salvinia",
"https://en.wikipedia.org/wiki/Salvinia_effect"
],
