"persona": "我的叶子排成一圈浮在水面，叶柄中间鼓起一个小气囊。秋天在水下摸到的那个带角的硬果子，就是菱角。",
"facts": [
"菱的叶子呈菱形，一圈圈排成莲座状浮在水面；叶柄中部膨大成充气的囊，负责把整圈叶子托起来。",
"日本古代把干硬的菱角撒在地上当\"铁蒺藜\"阻挡敌人，尖角能扎穿当时的鞋子。三菱集团的名字和标志也来自这种植物。",
"它和千屈菜、紫薇、石榴同属千屈菜科。在中国和印度，人们为了吃它的果实，已经栽培了至少 3000 年。"
],
