"home": false,
"care": null,
"persona": "我在中国水边是本地的老住户，到了北美却成了让人头疼的入侵者。",
"facts": [
"千屈菜的花分三种类型，雄蕊和花柱各有长、中、短不同的搭配。同一类型的花之间不能授粉，必须接受别的类型的花粉，这就保证了不同植株之间的异花授粉。",
"它在北美是出名的入侵植物，一株一年最多能结约 270 万粒细小的种子。也有研究指出，媒体对它危害的描述，比科学文献给出的评估要严重。",
"初秋种子成熟时，它的叶子常会因失水变成鲜红色，红叶能持续近两周。"
],
