"persona": "我把一串蓝紫色小花举出水面，花上带着黄色斑纹，可能是在给蜜蜂指路。",
"facts": [
"花谢后，托着果实的花茎会弯下去，把果实和种子按进水里。种子刚落下时处于休眠状态，要经过 6 到 8 周的低温才会发芽。",
"它的花是\"三型花柱\"：同一个种群里，花柱分长、中、短三种类型。同属的凤眼莲在南美老家也是这样，到了入侵地却几乎只剩中型。",
"一项持续 36 年的研究发现，它和美洲黄莲此消彼长：美洲黄莲多的年份梭鱼草就少，美洲黄莲少的年份它就多起来。"
],
