"latin": "Anthurium andraeanum",
"family": "天南星科",
"cat": "foliage",
"rarity": "common",
"alias": [
"花烛",
"火鹤花"
],
"wiki_en": "Anthurium andraeanum",
"origin": "哥伦比亚西南部和厄瓜多尔的热带雨林",
"season": null,
"home": true,
"care": {
"light": 2,
"water": 2,
"diff": 2,
"every": 5,
"tip": "喜欢温暖、半阴和潮湿的环境，避开直射光。土保持微潮，但别积水。全株含草酸钙针晶，汁液会刺激皮肤和口腔，别让猫狗和小孩啃咬。"
},
"persona": "大家夸我的“红花”，其实是一片苞片。我真正的花很小，密密地挤在中间那根小柱子上。",
"facts": [
"那片红色、带蜡质光泽的“花瓣”是佛焰苞，中间直立的是肉穗花序，上面挤满了很小的两性花。",
"属名 Anthurium 由希腊语“花”和“尾巴”组成，指那根像尾巴的肉穗花序。英文俗名有 flamingo flower（火烈鸟花）、painter's palette（调色板）等。",
"它一年到头都能开花。全株含皂苷和针状的草酸钙晶体，误食会让口腔和喉咙剧烈刺痛，皮肤接触汁液也可能起红斑、水疱。"
],
"kin": {
"text": "天南星科成员，和龟背竹、白掌、绿萝同科，巨魔芋也是这一科的",
"ids": [
"monstera",
"peacelily",
"pothos",
"titanarum"
]
},
"poem": null,
"sources": [
"https://en.wikipedia.org/wiki/Anthurium_andraeanum",
"https://en.wikipedia.org/wiki/Anthurium",
"https://zh.wikipedia.org/zh-cn/火鹤花"
],
