"alias": [
"铁丝草"
],
"wiki_en": "Adiantum capillus-veneris",
"origin": "世界各地温暖湿润的地区，中国也普遍分布，常长在溪边和湿润的岩石上",
"season": null,
"home": true,
"care": {
"light": 1,
"water": 3,
"diff": 3,
"every": 3,
"tip": "要散射光和很高的空气湿度。根要一直保持湿润但不能泡水，浇水宜勤、每次少量。冬天别低于 12℃。"
},
"persona": "我的叶柄又黑又亮，细得像铁丝。水洒到我叶子上，会直接滚下去。",
"facts": [
"属名 Adiantum 来自希腊语，意思是“不会被打湿”，它的叶片能让水珠直接滚落。英文俗名 venus hair fern，种加词 capillus-veneris 也是“维纳斯的头发”。",
"中文名来自它紫黑、细长又有光泽的叶柄，看上去像铁丝。它是钙质土的指示植物，野外常长在石灰岩、砂岩的湿润石壁上。",
"2020 年，捷克兹诺伊莫地下的 14 世纪地道里发现了它。那里潮湿，游客参观用的灯光又给了它光照，此后它在地道里扩散了不少。"
],
"kin": {
"text": "凤尾蕨科的蕨类，和鸟巢蕨、波士顿蕨、鹿角蕨同属水龙骨目",
"ids": [
"birdnest",
"bostonfern",
"staghorn"
]
},
