"latin": "Rhapis excelsa",
"family": "棕榈科",
"cat": "foliage",
"rarity": "common",
"alias": [
"观音竹"
],
"wiki_en": "Rhapis excelsa",
"origin": "中国南部和越南北部",
"season": null,
"home": true,
"care": {
"light": 2,
"water": 2,
"diff": 1,
"every": 7,
"tip": "喜欢温暖、半阴、通风的环境，怕烈日暴晒，比较耐寒，0℃ 左右也能过冬。土保持微潮。家里多在春天换盆时分株繁殖。ASPCA 把它列为对猫狗无毒。"
},
"persona": "我长得像一丛竹子，叶子却是一把把小扇子。我是棕榈家族的。",
"facts": [
"属名 Rhapis 是希腊语“针”的意思，种加词 excelsa 是拉丁语“高的”，可它在本属里并不算最高。",
"江户时代它经琉球传入日本，在那里叫“观音竹”，培育出许多斑叶品种。昭和初年和 1949 到 1951 年，它的价格两度暴涨，一度成了投机对象。",
"它通常雌雄异株。老叶鞘脱落后，露出一节节像竹子的茎，英文也叫它 bamboo palm。茎干可以做手杖和伞柄。"
],
"kin": {
"text": "棕榈科，和散尾葵、袖珍椰子同科",
"ids": [
"arecapalm",
"parlourpalm"
]
},
"poem": null,
