"home": false,
"care": null,
"persona": "我一开就是一大簇小白花。在老家我是篱笆上的常客，到了北美却成了让人头疼的入侵植物。",
"facts": [
"叶柄基部有一对边缘像梳齿一样的托叶，这是认它的好办法。花小，直径 1.5 到 4 厘米，一簇开很多朵，种名 multiflora 就是“多花的”。",
"它被引到北美，用来护坡、给牧场做活篱笆、招引野生动物，后来在美国东部成了入侵物种。一株一年能结约 50 万粒种子，种子在土里最长能存活 20 年。",
"园艺上常用它做嫁接月季的砧木。成簇开小花的 polyantha 类月季，就是从它的杂交后代里培育出来的。"
],
"kin": {
"text": "蔷薇科蔷薇属，和月季同属；桃、草莓也在这个科",
"ids": [
"chinarose",
"peach",
"strawberry"
]
},
"poem": null,
"sources": [
"https://en.wikipedia.org/wiki/Rosa_multiflora",
"https://zh.wikipedia.org/wiki/%E8%94%B7%E8%96%87"
],
