"rarity": "common",
"alias": [
"欧洲葡萄",
"提子",
"蒲陶"
],
"wiki_en": "Vitis vinifera",
"origin": "地中海沿岸至西亚、高加索",
"season": {
"months": [
7,
8,
9
],
"type": "果期"
},
"home": false,
"care": null,
"persona": "野生的我分雌株和雄株，得靠授粉才结果。人工栽培的我大多是两性花，自己就能结出一串串果子。",
"facts": [
"《史记·大宛列传》记载，大宛一带用\"蒲陶\"酿酒，\"汉使取其实来\"，汉武帝这才在肥沃的地里种起葡萄和苜蓿。后人常说是张骞带回来的，《史记》原文只写了\"汉使\"。",
"一种叫葡萄根瘤蚜的小虫对欧洲葡萄的伤害远比对北美葡萄大，曾在短短几年里让欧洲的葡萄酒生产遭受重创。后来人们把欧洲葡萄嫁接在北美葡萄的根上，这个办法沿用至今。",
"粤语把葡萄叫\"提子\"，两个词本来是一个意思。在中国大陆不说粤语的地方，\"提子\"常特指皮不易剥、果肉脆的鲜食品种。"
],
"kin": {
"text": "葡萄科，墙上的爬山虎是它的亲戚",
"ids": [
"boston"
]
},
"poem": {
"line": "葡萄美酒夜光杯，欲饮琵琶马上催。",
"src": "王翰《凉州词》"
},
