"persona": "我开黄花，草莓开白花，分辨我们俩先看花。我的红果子摘下来咬一口，几乎没什么味道。",
"facts": [
"红色的\"果子\"是膨大的花托，表面一粒粒的才是瘦果，结构和草莓很像。叶绿体基因的证据显示它属于委陵菜属，所以不少资料已改用学名 Potentilla indica。",
"它的黄色花瓣中心有一块蜜导，只在紫外光下才显出来。人眼看去是一片纯黄，能看见紫外光的昆虫却能看到花心的标记。",
"民间常说蛇莓有毒。英文资料记载它的果实可以吃，只是远不如草莓好吃。路边的蛇莓可能沾了农药和尘土，也容易和别的红色野果认错，最好别随手摘来吃。"
],
"kin": {
"text": "蔷薇科，和草莓同科不同属",
"ids": [
"strawberry",
"multiflora"
]
},
"poem": null,
"sources": [
"https://en.wikipedia.org/wiki/Potentilla_indica",
"https://zh.wikipedia.org/wiki/蛇莓",
"https://shflora.ibiodiversity.net/Pages/Duchesnea_indica.html"
],
