"home": false,
"care": null,
"persona": "春天我抽出白丝绒一样的花穗。地下的根状茎占了我六成的分量，割掉地上部分，我很快又长回来。",
"facts": [
"在中国它是本土野草。到了美国东南部，它成了出名的入侵杂草：2003 年的调查显示，它在当地占据的面积已经超过了以难缠著称的葛藤。一小段一寸长的根状茎就能重新长出一株。",
"它很容易着火，看着还绿的时候也能烧起来。大火烧死周围的树苗，它自己靠没受损的地下根状茎很快又长满一片。",
"它的叶缘有细锯齿，嵌着锋利的硅质晶体，徒手去拔很容易被割伤手。"
],
"kin": {
"text": "禾本科，和芦苇、狗尾草、牛筋草同科",
"ids": [
"reed",
"foxtail",
"goosegrass"
]
},
"poem": {
"line": "野有死麕，白茅包之。",
"src": "《诗经·召南·野有死麕》"
},
