"family": "天南星科",
"cat": "water",
"rarity": "common",
"alias": [
"大萍",
"水芙蓉"
],
"wiki_en": "Pistia",
"origin": "原产地不确定，可能是泛热带；现已遍布全球热带和亚热带淡水",
"season": null,
"home": false,
"care": null,
"persona": "我长得像一棵漂在水上的生菜，其实是天南星科的。请别把我放进河塘，我长得太快了。",
"facts": [
"它是入侵物种。2022 年被列入中国《重点管理外来入侵物种名录》。它在水面铺成厚垫后会阻断气体交换，让水里缺氧，还会缠住船的螺旋桨；欧盟也从 2024 年 8 月起禁止它。",
"它和龟背竹、浮萍同属天南星科，是大薸属唯一的一种。花很小，没有花瓣，藏在叶丛中央的小佛焰苞里，一根肉穗上只有 1 朵雌花和 2～8 朵雄花。",
"叶面密生白色短毛，毛之间能兜住小气泡；叶片里还有大量海绵状的通气组织，所以它能稳稳地浮在水上。"
],
"kin": {
"text": "天南星科，和龟背竹、绿萝、浮萍同科",
"ids": [
"monstera",
"pothos",
"duckweed"
]
},
"poem": null,
"sources": [
"https://en.wikipedia.org/wiki/Pistia",
"https://zh.wikipedia.org/wiki/大薸",
"https://www.plantplus.cn/ias/news/45",
"https://www.moa.gov.cn/govpublic/KJJYS/202211/t20221109_6415160.htm"
],
